public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long[][][] dp = new long[101][101][101];

        // Precompute dp
        for (int wx = 0; wx <= 100; wx++) {
            for (int wy = 0; wy <= 100; wy++) {
                for (int sx = 0; sx <= 100; sx++) {
                    dp[wx][wy][sx] = -1;
                }
            }
        }

        while (true) {
            int wx = sc.nextInt();
            int wy = sc.nextInt();
            int sx = sc.nextInt();
            int sy = sc.nextInt();
            int n = sc.nextInt();

            if (wx == 0 && wy == 0 && sx == 0 && sy == 0 && n == 0) break;

            long result = solve(wx, wy, sx, sy, n, dp);
            System.out.println(result);
        }
        sc.close();
    }

    static long solve(int wx, int wy, int sx, int sy, int n, long[][][] dp) {
        if (wx < 0 || wy < 0 || sx < 0 || sy < 0) return 0;
        if (n == 0) {
            if (wx == 0 && wy == 0 && sx == 0 && sy == 0) return 1;
            return 0;
        }
        if (dp[wx][wy][sx] != -1) return dp[wx][wy][sx];

        long total = 0;
        // Try all possible scores for a match
        for (int xs = 0; xs <= sx; xs++) {
            for (int ys = 0; ys <= sy; ys++) {
                if (xs == 0 && ys == 0) continue;
                if (xs > ys) {
                    // X wins
                    total += solve(wx - 1, wy, sx - xs, sy - ys, n - 1, dp);
                } else if (xs == ys) {
                    // Draw
                    total += solve(wx, wy, sx - xs, sy - ys, n - 1, dp);
                } else {
                    // Y wins
                    total += solve(wx, wy - 1, sx - xs, sy - ys, n - 1, dp);
                }
                total %= MOD;
            }
        }

        dp[wx][wy][sx] = total;
        return total;
    }
}

