public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int c = fs.nextInt();
            int d = fs.nextInt();
            int e = fs.nextInt();

            if (a == 0 && b == 0 && c == 0 && d == 0 && e == 0) break;

            // Interpret input as:
            // a = number of matches won by X
            // b = number of draws
            // c = number of matches won by Y
            // d = total score of X
            // e = total score of Y
            //
            // Count ordered sequences of matches satisfying:
            //   X-wins count = a, draws count = b, Y-wins count = c
            //   total X goals = d, total Y goals = e

            int xWins = a, draws = b, yWins = c, sx = d, sy = e;
            int n = xWins + draws + yWins;

            long waysScores = countScoreMultisetsOrderedByResult(xWins, draws, yWins, sx, sy);
            long waysOrder = multinomial(n, xWins, draws, yWins);

            long ans = waysScores * waysOrder % MOD;
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    // Count number of ways to choose score pairs for each match position if result type sequence were fixed:
    // xWins matches must satisfy xi > yi
    // draws matches xi = yi
    // yWins matches xi < yi
    // total sums sx, sy
    //
    // Since matches are distinguishable once result-type positions are fixed, this is coefficient counting.
    static long countScoreMultisetsOrderedByResult(int xWins, int draws, int yWins, int sx, int sy) {
        // DP over groups:
        // For one X-win match generating function: sum_{u>v>=0} p^u q^v
        // For one draw: sum_{t>=0} p^t q^t
        // For one Y-win: sum_{u<v} p^u q^v
        //
        // Use repeated convolution by simple transitions.
        long[][] dp = new long[sx + 1][sy + 1];
        dp[0][0] = 1;

        for (int i = 0; i < xWins; i++) {
            long[][] ndp = new long[sx + 1][sy + 1];
            for (int x = 0; x <= sx; x++) {
                for (int y = 0; y <= sy; y++) {
                    long cur = dp[x][y];
                    if (cur == 0) continue;
                    for (int vy = 0; y + vy <= sy; vy++) {
                        for (int ux = vy + 1; x + ux <= sx; ux++) {
                            ndp[x + ux][y + vy] += cur;
                            if (ndp[x + ux][y + vy] >= MOD) ndp[x + ux][y + vy] -= MOD;
                        }
                    }
                }
            }
            dp = ndp;
        }

        for (int i = 0; i < draws; i++) {
            long[][] ndp = new long[sx + 1][sy + 1];
            for (int x = 0; x <= sx; x++) {
                for (int y = 0; y <= sy; y++) {
                    long cur = dp[x][y];
                    if (cur == 0) continue;
                    int lim = Math.min(sx - x, sy - y);
                    for (int t = 0; t <= lim; t++) {
                        ndp[x + t][y + t] += cur;
                        if (ndp[x + t][y + t] >= MOD) ndp[x + t][y + t] -= MOD;
                    }
                }
            }
            dp = ndp;
        }

        for (int i = 0; i < yWins; i++) {
            long[][] ndp = new long[sx + 1][sy + 1];
            for (int x = 0; x <= sx; x++) {
                for (int y = 0; y <= sy; y++) {
                    long cur = dp[x][y];
                    if (cur == 0) continue;
                    for (int ux = 0; x + ux <= sx; ux++) {
                        for (int vy = ux + 1; y + vy <= sy; vy++) {
                            ndp[x + ux][y + vy] += cur;
                            if (ndp[x + ux][y + vy] >= MOD) ndp[x + ux][y + vy] -= MOD;
                        }
                    }
                }
            }
            dp = ndp;
        }

        return dp[sx][sy];
    }

    static long multinomial(int n, int a, int b, int c) {
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
        return fact[n] * invFact[a] % MOD * invFact[b] % MOD * invFact[c] % MOD;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

