            break;
        }

        int total_matches = wx + wy + d;

        // Initialize dp
        memset(dp, 0, sizeof(dp));
        dp[0][0][0] = 1;

        // dp[k][i][j] = ways to have k matches with total score X = i, Y = j
        for (int k = 0; k < total_matches; k++) {
            for (int i = 0; i <= sx; i++) {
                for (int j = 0; j <= sy; j++) {
                    if (dp[k][i][j] == 0) continue;

                    long long current = dp[k][i][j];

                    if (k < wx) {
                        // X wins: x > y
                        for (int y = 0; y <= sy - j; y++) {
                            for (int x = y + 1; x <= sx - i; x++) {
                                dp[k+1][i+x][j+y] = (dp[k+1][i+x][j+y] + current) % MOD;
                            }
                        }
                    }
                    else if (k < wx + wy) {
                        // Y wins: y > x
                        for (int x = 0; x <= sx - i; x++) {
                            for (int y = x + 1; y <= sy - j; y++) {
                                dp[k+1][i+x][j+y] = (dp[k+1][i+x][j+y] + current) % MOD;
                            }
                        }
                    }
                    else {
                        // Draw: x = y
                        for (int s = 0; s <= min(sx - i, sy - j); s++) {
                            dp[k+1][i+s][j+s] = (dp[k+1][i+s][j+s] + current) % MOD;
                        }
                    }
                }
            }
        }

        long long result = dp[total_matches][sx][sy];

        // Multiply by permutations of matches
        // Number of ways to order matches = total_matches! / (wx! * wy! * d!)
        long long fact[105];
        fact[0] = 1;
        for (int i = 1; i <= total_matches; i++) {
            fact[i] = (fact[i-1] * i) % MOD;
        }

        long long denom = (fact[wx] * fact[wy] % MOD) * fact[d] % MOD;

        // Modular inverse using Fermat's little theorem
        auto modpow = [](long long base, long long exp) {
            long long result = 1;
            while (exp > 0) {
                if (exp & 1) result = (result * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return result;
        };

        long long inv_denom = modpow(denom, MOD - 2);
        result = (result * fact[total_matches] % MOD) * inv_denom % MOD;

        cout << result << "\n";
    }

    return 0;
}

