using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n, xw, yw, sx, sy;
        cin >> n >> xw >> yw >> sx >> sy;
        if (!cin) return 0;
        if (n == 0 && xw == 0 && yw == 0 && sx == 0 && sy == 0) break;

        int d = n - xw - yw; // number of draws
        if (d < 0) {
            cout << 0 << '\n';
            continue;
        }

        // dp[a][b][c]:
        // after processing some matches,
        // a = number of X wins used
        // b = number of Y wins used
        // c = total score of X used
        // Y score used is tracked implicitly by current layer index and transitions.
        //
        // We process matches one by one.
        vector<vector<vector<long long>>> dp(
            xw + 1,
            vector<vector<long long>>(yw + 1, vector<long long>(sx + 1, 0))
        );
        dp[0][0][0] = 1;

        for (int played = 0; played < n; ++played) {
            vector<vector<vector<long long>>> ndp(
                xw + 1,
                vector<vector<long long>>(yw + 1, vector<long long>(sx + 1, 0))
            );

            for (int a = 0; a <= xw; ++a) {
                for (int b = 0; b <= yw; ++b) {
                    int usedDraws = played - a - b;
                    if (usedDraws < 0 || usedDraws > d) continue;

                    for (int px = 0; px <= sx; ++px) {
                        long long cur = dp[a][b][px];
                        if (!cur) continue;

                        // We need current used Y score too, but it is not stored.
                        // So this state compression is insufficient.
                    }
                }
            }

            // We actually need both score sums. Use sparse map DP per layer.
            // This loop body is intentionally not used.
        }

        // Correct sparse DP:
        // state: (xWinsUsed, yWinsUsed, xScoreUsed, yScoreUsed)
        // Since scores can be moderately large, use unordered_map per (a,b,px,py) packed.
        unordered_map<long long, long long> cur, nxt;
        auto pack = [&](int a, int b, int px, int py) -> long long {
            // safe packing in 64-bit
            return (((long long)a * (yw + 1) + b) * (sx + 1) + px) * (sy + 1) + py;
        };

        cur.reserve(1 << 14);
        cur[pack(0, 0, 0, 0)] = 1;

        for (int played = 0; played < n; ++played) {
            nxt.clear();

            for (auto &it : cur) {
                long long key = it.first;
                long long ways = it.second;

                int py = key % (sy + 1); key /= (sy + 1);
                int px = key % (sx + 1); key /= (sx + 1);
                int b = key % (yw + 1); key /= (yw + 1);
                int a = (int)key;
                int usedDraws = played - a - b;
                if (usedDraws < 0 || usedDraws > d) continue;

                int remMatches = n - played - 1;

                // Add one X-win match: score (i,j) with i>j>=0
                if (a < xw) {
                    for (int j = 0; py + j <= sy; ++j) {
                        for (int i = j + 1; px + i <= sx; ++i) {
                            // Feasibility pruning for remaining matches
                            int na = a + 1, nb = b, npx = px + i, npy = py + j;
                            int remXWins = xw - na, remYWins = yw - nb;
                            int remDraws = d - usedDraws;

                            int rx = sx - npx, ry = sy - npy;
                            if (rx < remXWins) continue; // each future X-win contributes at least 1 to X
                            if (ry < remYWins) continue; // each future Y-win contributes at least 1 to Y

                            long long nk = pack(na, nb, npx, npy);
                            long long &ref = nxt[nk];
                            ref += ways;
                            if (ref >= MOD) ref -= MOD;
                        }
                    }
                }

                // Add one Y-win match: score (i,j) with j>i>=0
                if (b < yw) {
                    for (int i = 0; px + i <= sx; ++i) {
                        for (int j = i + 1; py + j <= sy; ++j) {
                            int na = a, nb = b + 1, npx = px + i, npy = py + j;
                            int remXWins = xw - na, remYWins = yw - nb;
                            int remDraws = d - usedDraws;

                            int rx = sx - npx, ry = sy - npy;
                            if (rx < remXWins) continue;
                            if (ry < remYWins) continue;

                            long long nk = pack(na, nb, npx, npy);
                            long long &ref = nxt[nk];
                            ref += ways;
                            if (ref >= MOD) ref -= MOD;
                        }
                    }
                }

                // Add one draw match: score (t,t)
                if (usedDraws < d) {
                    for (int t = 0; px + t <= sx && py + t <= sy; ++t) {
                        int na = a, nb = b, npx = px + t, npy = py + t;
                        int remXWins = xw - na, remYWins = yw - nb;
                        int remDraws = d - (usedDraws + 1);

                        int rx = sx - npx, ry = sy - npy;
                        if (rx < remXWins) continue;
                        if (ry < remYWins) continue;
                        // draws can always be 0:0, so no extra lower bound from remDraws

                        long long nk = pack(na, nb, npx, npy);
                        long long &ref = nxt[nk];
                        ref += ways;
                        if (ref >= MOD) ref -= MOD;
                    }
                }
            }

            cur.swap(nxt);
        }

        auto it = cur.find(pack(xw, yw, sx, sy));
        cout << (it == cur.end() ? 0 : it->second % MOD) << '\n';
    }

    return 0;
}

