#define MOD 1000000007
#define MAX_SCORE 800

long long comb[MAX_SCORE + 1][MAX_SCORE + 1];
long long dp[MAX_SCORE + 1][MAX_SCORE + 1];

void init_comb() {
    for (int i = 0; i <= MAX_SCORE; i++) {
        comb[i][0] = comb[i][i] = 1;
        for (int j = 1; j < i; j++) {
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD;
        }
    }
}

int main() {
    init_comb();

    // dp[w][s] = number of ways to have w wins and total score s (for one team)
    dp[0][0] = 1;
    for (int w = 0; w <= MAX_SCORE; w++) {
        for (int s = 0; s <= MAX_SCORE; s++) {
            if (dp[w][s] == 0) continue;
            // Add a win: score x for us, y for opponent, x > y
            for (int x = 1; x + s <= MAX_SCORE && w + 1 <= MAX_SCORE; x++) {
                for (int y = 0; y < x; y++) {
                    if (s + x <= MAX_SCORE) {
                        dp[w+1][s+x] = (dp[w+1][s+x] + dp[w][s]) % MOD;
                    }
                }
            }
        }
    }

    int a, b, c, d, e;
    while (1) {
        scanf("%d %d %d %d %d", &a, &b, &c, &d, &e);
        if (a == 0 && b == 0 && c == 0 && d == 0 && e == 0) break;

        int wx = a, wy = b;
        int sx = c, sy = d;
        int draws = e;

        // Total matches = winsX + winsY + draws
        int total_matches = wx + wy + draws;

        // First, arrange the order of wins/losses/draws
        // Number of sequences = total_matches! / (wx! * wy! * draws!)
        // Compute using combinations
        long long ways_order = 1;
        int remaining = total_matches;
        // Choose positions for draws
        if (draws > 0) {
            long long choose = 1;
            for (int i = 0; i < draws; i++) {
                choose = choose * (remaining - i) % MOD;
                choose = choose * modinv(i+1) % MOD; // need modular inverse
            }
            // Actually simpler: use precomputed comb
            ways_order = comb[remaining][draws];
            remaining -= draws;
        }
        if (wx > 0) {
            ways_order = ways_order * comb[remaining][wx] % MOD;
            remaining -= wx;
        }
        // wy is determined

        // Now for each win, we need to assign scores
        // For team X wins: total score sx from wx wins, each win contributes x > y
        // For team Y wins: total score sy from wy wins, each win contributes y > x
        // For draws: each draw contributes equal scores, but they don't affect total wins

        // We need to count ways to assign scores to each match such that:
        // - In wx wins of X: sum of X scores = sx, sum of Y scores = some value (not constrained)
        // - In wy wins of Y: sum of Y scores = sy, sum of X scores = some value
        // - In draws: sum of X scores = sum of Y scores

        // Let's precompute for a team with w wins and total score s:
        // number of ways to assign scores (x_i, y_i) with x_i > y_i for each win
        // This is exactly dp[w][s] defined above

        long long ways_x = dp[wx][sx];
        long long ways_y = dp[wy][sy];

        // For draws: each draw has equal scores, so we need to partition the remaining scores
        // Let remaining score for X = some value, same for Y
        // We need to assign scores to draws such that sum of X scores = sum of Y scores = some value r
        // Number of ways: for each draw, we choose a score (same for both), so it's stars and bars
        // Number of ways to have draws with total score r = C(r + draws - 1, draws - 1)
        // But r can be any value from 0 to min(remaining_X, remaining_Y)
        // Actually remaining scores are not directly given; we have total scores for X and Y already
        // The draws contribute equally to both sides, so let D be the total score from draws for each team
        // Then we have: sx = sum of X scores in wins + D
        //               sy = sum of Y scores in wins + D
        // So D must satisfy: D = sx - sum_X_wins = sy - sum_Y_wins
        // But sum_X_wins is exactly sx from dp, and sum_Y_wins is sy from dp
        // Wait, that's confusing. Let's think again.

        // Actually dp[wx][sx] already accounts for the sum of X scores in wins being exactly sx.
        // Similarly for Y. So the draws must contribute equal amounts to both teams.
        // Let D be the common score from draws for each team.
        // Then total X score = sx + D, total Y score = sy + D
        // But the input gives total scores directly as c and d.
        // So we have: c = sx + D, d = sy + D
        // Therefore D = c - sx = d - sy
        // This means that for a valid arrangement, we must have c - sx == d - sy >= 0

        // So we need to sum over all possible sx, sy such that:
        // dp[wx][sx] > 0, dp[wy][sy] > 0, and c - sx == d - sy >= 0
        // Then multiply by ways to assign draws with total D for each team

        long long ans = 0;
        for (int sx_val = 0; sx_val <= c; sx_val++) {
            if (dp[wx][sx_val] == 0) continue;
            int D = c - sx_val;
            if (D < 0) continue;
            int sy_val = d - D;
            if (sy_val < 0 || sy_val > MAX_SCORE) continue;
            if (dp[wy][sy_val] == 0) continue;

            // Number of ways to assign draw scores: each draw gets some score k >= 0
            // Sum of draw scores for each team = D
            // Number of nonnegative integer solutions to k1 + ... + k_draws = D
            // = C(D + draws - 1, draws - 1) if draws > 0, else 1 if D == 0
            long long ways_draw = 1;
            if (draws > 0) {
                ways_draw = comb[D + draws - 1][draws - 1];
            } else {
                if (D != 0) ways_draw = 0;
            }

            long long cur = ways_order * dp[wx][sx_val] % MOD;
            cur = cur * dp[wy][sy_val] % MOD;
            cur = cur * ways_draw % MOD;
            ans = (ans + cur) % MOD;
        }

        printf("%lld\n", ans);
    }

    return 0;
}

