#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int A, B, C, P, Q;

    while (scanf("%d %d %d %d %d", &A, &B, &C, &P, &Q) == 5) {
        if (A == 0 && B == 0 && C == 0 && P == 0 && Q == 0) break;

        int N = A + B + C;

        /* Let:
           - A matches: X wins, contribution di = xi-yi >= 1
           - B matches: Y wins, contribution ej = yj-xj >= 1
           - C matches: draws, contribution tk = xk = yk >= 0

           Then:
             sum(di) - sum(ej) = P - Q
             sum(di) + sum(ej) + 2*sum(tk) = P + Q

           Hence if U = sum(di), V = sum(ej), T = sum(tk):
             U - V = P - Q
             U + V = P + Q - 2T

           Equivalently choose S = U+V, where:
             S ≡ P+Q (mod 2), 0 <= S <= P+Q
             U = (S + (P-Q))/2 = P - T
             V = (S - (P-Q))/2 = Q - T
           More directly, choose T with:
             0 <= T <= min(P,Q)
             U = P - T >= A
             V = Q - T >= B

           For fixed T:
             number of ways to split U into A positive parts = C(U-1, A-1) (or 1 if A=0 and U=0)
             number of ways to split V into B positive parts = C(V-1, B-1) (or 1 if B=0 and V=0)
             number of ways to split T into C nonnegative parts = C(T+C-1, C-1) (or 1 if C=0 and T=0)

           Also choose which match positions are X-wins / Y-wins / draws:
             N! / (A! B! C!)
        */

        if ((ll)A + B + C == 0) {
            printf("%d\n", (P == 0 && Q == 0) ? 1 : 0);
            continue;
        }

        int maxV = P + Q + C + 5;
        int maxN = maxV + N + 5;
        if (maxN < 10) maxN = 10;

        ll *fact = (ll*)malloc(sizeof(ll) * (maxN + 1));
        ll *invfact = (ll*)malloc(sizeof(ll) * (maxN + 1));

        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) fact[i] = fact[i - 1] * i % MOD;
        invfact[maxN] = mod_pow(fact[maxN], MOD - 2);
        for (int i = maxN; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

        #define COMB(n,r) (((r) < 0 || (r) > (n)) ? 0LL : fact[(n)] * invfact[(r)] % MOD * invfact[(n)-(r)] % MOD)

        ll arrange = fact[N] * invfact[A] % MOD * invfact[B] % MOD * invfact[C] % MOD;

        ll ans = 0;
        int tmin = 0;
        if (P - A < tmin) tmin = tmin;
        if (Q - B < tmin) tmin = tmin;
        int tmax = P < Q ? P : Q;

        for (int T = 0; T <= tmax; T++) {
            int U = P - T;
            int V = Q - T;
            if (U < A || V < B) continue;

            ll waysU, waysV, waysT;

            if (A == 0) waysU = (U == 0 ? 1 : 0);
            else waysU = COMB(U - 1, A - 1);

            if (B == 0) waysV = (V == 0 ? 1 : 0);
            else waysV = COMB(V - 1, B - 1);

            if (C == 0) waysT = (T == 0 ? 1 : 0);
            else waysT = COMB(T + C - 1, C - 1);

            ll add = waysU * waysV % MOD * waysT % MOD;
            ans += add;
            if (ans >= MOD) ans -= MOD;
        }

        ans = ans * arrange % MOD;
        printf("%lld\n", ans);

        free(fact);
        free(invfact);
    }

    return 0;
}

import sys

MOD = 1_000_000_007

MAXN = 2000  # enough for typical constraints, adjust if needed

fact = [1] * (MAXN + 1)
inv_fact = [1] * (MAXN + 1)
for i in range(1, MAXN + 1):
    fact[i] = fact[i-1] * i % MOD

inv_fact[MAXN] = pow(fact[MAXN], MOD-2, MOD)
for i in range(MAXN, 0, -1):
    inv_fact[i-1] = inv_fact[i] * i % MOD

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

def solve():
    out_lines = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = list(map(int, line.split()))
        if len(parts) != 5:
            continue
        Wx, Wy, D, Sx, Sy = parts
        if Wx == 0 and Wy == 0 and D == 0 and Sx == 0 and Sy == 0:
            break

        total_matches = Wx + Wy + D
        P = Sx - Sy
        ans = 0

        for A in range(Wx, Sx + 1):
            B = A - P
            if B < Wy or B > Sy:
                continue
            if Sx - A != Sy - B:
                continue
            rem = Sx - A
            if rem < 0:
                continue

            ways_margins = nCr(A-1, Wx-1) * nCr(B-1, Wy-1) % MOD
            if D == 0:
                ways_draws = 1 if rem == 0 else 0
            else:
                ways_draws = nCr(rem + D - 1, D - 1)
            if ways_draws == 0:
                continue

            ways_order = fact[total_matches] * inv_fact[Wx] % MOD
            ways_order = ways_order * inv_fact[Wy] % MOD
            ways_order = ways_order * inv_fact[D] % MOD

            ans = (ans + ways_margins * ways_draws % MOD * ways_order) % MOD

        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
